+	for _, chain := range req.TLS.VerifiedChains {
 		user, ok, err := a.user.User(chain)
 		if err != nil {
 			errlist = append(errlist, err)
@@ -174,22 +157,6 @@ func (a *Verifier) AuthenticateRequest(req *http.Request) (*authenticator.Respon
